record Pt(double x, double y) { }

public record Segment(Pt a, Pt b) {

    public double length() {
        double dx = b.x() - a.x();
        double dy = b.y() - a.y();
        return Math.sqrt(dx * dx + dy * dy);
    }

    public Pt midpoint() {
        return new Pt((a.x() + b.x()) / 2.0, (a.y() + b.y()) / 2.0);
    }
}
